(function(){'use strict';var e=[["GET", "Discover endpoints", "/api/myshopify", "Return endpoints and whether Shopify credentials are configured."], ["GET", "List products", "/api/myshopify/products", "List locally imported Shopify products."], ["GET", "Get product", "/api/myshopify/products/:id", "Get an imported product."], ["GET", "List customers", "/api/myshopify/customers", "List locally imported Shopify customers."], ["GET", "Get customer", "/api/myshopify/customers/:id", "Get an imported customer."], ["GET", "List orders", "/api/myshopify/orders", "List locally imported Shopify orders."], ["GET", "Get order", "/api/myshopify/orders/:id", "Get an imported order and its stored line items."], ["GET", "List categories", "/api/myshopify/categories", "List imported Shopify collections."], ["GET", "Get category", "/api/myshopify/categories/:id", "Get an imported category."], ["GET", "List discounts", "/api/myshopify/discounts", "List imported Shopify discounts."], ["GET", "Get discount", "/api/myshopify/discounts/:id", "Get an imported discount."], ["GET", "List identity maps", "/api/myshopify/maps/:type", "List products, customers, categories or orders identity mappings."], ["GET", "List sync logs", "/api/myshopify/logs", "List synchronization logs with direction, entity_type and status filters."], ["GET", "Get sync log", "/api/myshopify/logs/:id", "Get one synchronization log."], ["POST", "Run reconciliation", "/api/myshopify/sync", "Pull changed Shopify records and push mapped Perfex categories."], ["POST", "Register webhooks", "/api/myshopify/webhooks/register", "Register all required event topics with Shopify."], ["POST", "Push customer", "/api/myshopify/push/customer/:id", "Push a Perfex customer to Shopify."], ["POST", "Push item", "/api/myshopify/push/item/:id", "Push a Perfex item and mapped stock to Shopify."], ["POST", "Push inventory", "/api/myshopify/push/inventory", "Push all mapped Warehouse inventory levels."], ["POST", "Push categories", "/api/myshopify/push/categories", "Push Perfex item groups to Shopify collections."]];function x(v){return String(v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}function a(m,t){return'api-myshopify-'+m.toLowerCase()+'-'+t.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}function section(){var c=document.getElementById('content');if(!c)return false;if(document.getElementById('api-myshopify'))return true;var s=document.createElement('section');s.id='api-myshopify';s.innerHTML='<h2>MyShopify</h2><article><h1>MyShopify endpoints</h1><div class="endpoint-desc"><p>Inspect imported Shopify data, mappings and logs, run reconciliation, register webhooks, and push Perfex records to Shopify.</p><p>The module and credentials must be active. Authenticate with <code>authtoken</code>.</p></div></article>'+e.map(function(r){return'<article id="'+a(r[0],r[1])+'"><h1>'+x(r[1])+'</h1><div class="row pre-post"><div class="col-md-7 no-float"><pre class="full-pre"><span class="typ typ-'+r[0].toLowerCase()+'">'+r[0]+'</span><span class="url">'+x(r[2])+'</span></pre><p>'+x(r[3])+'</p></div></div></article>'}).join('');c.insertBefore(s,document.getElementById('api-custom-fields')||null);return true}function nav(){var n=document.querySelector('#sidenav ul.sidenav');if(!n)return false;if(n.querySelector('[data-myshopify-nav]'))return true;var h=document.createElement('li');h.className='nav-header nav-list-item';h.setAttribute('data-myshopify-nav','true');h.innerHTML='<a href="#api-myshopify">MyShopify</a>';n.appendChild(h);e.forEach(function(r){var i=document.createElement('li');i.className='nav-list-item';i.innerHTML='<a href="#'+a(r[0],r[1])+'"><span class="typ-name typ-'+r[0].toLowerCase()+'">'+r[0]+'</span><span class="nav-title">'+x(r[1])+'</span></a>';n.appendChild(i)});return true}function go(){return section()&&nav()}function start(){go();var o=new MutationObserver(go);o.observe(document.documentElement,{childList:true,subtree:true});setTimeout(function(){go();o.disconnect()},5000)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start()}());